ssize_t stream_file_zero_copy(int sock_fd, int file_fd, off_t *offset, size_t remaining) {
    int eagain_retries = 0;
    const int max_eagain_retries = 5;
    while (remaining > 0) {
        ssize_t sent = sendfile(sock_fd, file_fd, offset, remaining);
        if (sent > 0) {
            remaining -= (size_t)sent;
            eagain_retries = 0;
            continue;
        }
        if (sent == 0) break; // EOF reached
        if (errno == EINTR) continue; // Interrupted by signal, retry immediately
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            if (++eagain_retries > max_eagain_retries) {
                return -1; // Caller should re-arm epoll EPOLLOUT and resume from *offset
            }
            usleep(1000 * (1 << (eagain_retries - 1))); // Bounded backoff before yielding
            continue;
        }
        return -1; // Fatal socket or file error: caller closes/cleans up descriptor
    }
    return 0;
}
